/**
 * Worker entry: OpenNext's generated handler plus a `scheduled()` hook so
 * Cloudflare Cron Triggers drive the same /api/cron/* routes Vercel Cron
 * does today. The request is dispatched in-process through the handler's
 * own fetch (no public round trip) with the bearer secret the routes expect.
 */
// @ts-expect-error — generated by `opennextjs-cloudflare build`; not in git.
import handler from "../.open-next/worker.js";

import { jobForSchedule } from "../src/lib/cron/schedules";

// Durable Object classes used by the cache overrides (open-next.config.ts).
// @ts-expect-error — generated file, see above.
export { DOQueueHandler, DOShardedTagCache } from "../.open-next/worker.js";

type Env = {
  CRON_SECRET?: string;
  /**
   * "1" only on the Worker that is serving production traffic. Until the
   * DNS cutover, Vercel Cron runs the jobs; a second scheduler against the
   * same database would double-send alerts and race on `sla_alerted_at`.
   */
  CRON_ENABLED?: string;
  NEXT_PUBLIC_SITE_URL?: string;
};

/**
 * OpenNext marks /_next/image responses immutable only for images imported
 * in code; every /public image (all of ours) comes back with no
 * Cache-Control, so browsers re-download them on each visit. Give those a
 * day fresh plus a week of stale-while-revalidate.
 */
const IMAGE_CACHE_CONTROL = "public, max-age=86400, stale-while-revalidate=604800";

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const res: Response = await handler.fetch(request, env, ctx);
    if (res.status !== 200 || res.headers.has("cache-control")) return res;
    if (!new URL(request.url).pathname.startsWith("/_next/image")) return res;
    const out = new Response(res.body, res);
    out.headers.set("cache-control", IMAGE_CACHE_CONTROL);
    return out;
  },

  async scheduled(event: ScheduledEvent, env: Env, ctx: ExecutionContext) {
    const job = jobForSchedule(event.cron);
    if (!job) {
      console.warn(`[cron] no job for expression "${event.cron}"`);
      return;
    }
    if (env.CRON_ENABLED !== "1") {
      console.log("[cron] CRON_ENABLED is not 1; skipping", job.path);
      return;
    }
    if (!env.CRON_SECRET) {
      console.warn("[cron] CRON_SECRET is not set; skipping", job.path);
      return;
    }
    const origin = (env.NEXT_PUBLIC_SITE_URL ?? "https://www.mmg-lawfirm.com").replace(/\/$/, "");
    const request = new Request(`${origin}${job.path}`, {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      handler
        .fetch(request, env, ctx)
        .then((res: Response) => {
          if (!res.ok) console.error(`[cron] ${job.path} → HTTP ${res.status}`);
        })
        .catch((err: unknown) => console.error(`[cron] ${job.path} failed`, err)),
    );
  },
} satisfies ExportedHandler<Env>;
